  @suffix " [JQ-802] " <> @docs <> "JQ-802"
  @coded Jason.encode!(%{
           "error" => %{
             "code" => "sdk_too_old",
             "jq_code" => "JQ-802",
             "docs_url" => "https://evil.example/x",
