  test "a 426 with a registry code ends its message and its log line with it" do
    assert {:error, %SdkTooOldError{jq_code: "JQ-802"} = error} = Transport.result(426, @coded)
    assert error.docs_url == @docs <> "JQ-802"

    assert error.message == @message
    assert Exception.message(error) == @message <> @suffix
    assert SdkTooOldError.log_line(error) == "joobq: " <> @message <> @suffix

    assert {:error, %SdkTooOldError{jq_code: nil, docs_url: nil}} =
             Transport.result(426, String.replace(@coded, "JQ-802", "JQ-1"))
