    assert Exception.message(error) =~ "426 sdk_too_old"
    assert Exception.message(error) =~ "<html>upgrade</html>"

    assert SdkTooOldError.log_line(error) ==
             "joobq: HTTP 426 from the gateway without the sdk_too_old code (a proxy in the path may be answering): " <>
               "<html>upgrade</html>"

    assert {:error, %SdkTooOldError{code: ""}} =
             Transport.result(426, ~s({"error":{"details":7}}))
  end

  test "the gateway's text is one clean line, cut to 300 characters" do
    message = "  old\r\n\tsdk\u202Ehere\u0007  " <> String.duplicate("é", 400)

    body =
      Jason.encode!(%{
        "error" => %{
          "code" => "sdk_too_old",
          "message" => message,
          "details" => %{"min" => "0.7\n"}
