    assert {:error, %SdkTooOldError{} = error} = Transport.result(426, body)
    assert String.starts_with?(error.message, "old sdkhere éé")
    assert String.length(error.message) == 300
    assert error.min == "0.7"
    assert SdkTooOldError.log_line(error) == "joobq: " <> error.message

    blank = Jason.encode!(%{"error" => %{"code" => "sdk_too_old", "message" => " \u2066\t "}})
    assert {:error, %SdkTooOldError{message: ""} = error} = Transport.result(426, blank)
    assert Exception.message(error) =~ "426 sdk_too_old"
